package com.medicarepro;
import java.sql.*; import java.util.*;
public final class ClinicRepository {
 public record Patient(long id,String name,int age,String contact,String doctor,String diagnosis,String status,long owner){ }
 private final Database db; public ClinicRepository(Database db){this.db=db;}
 public List<Patient> patients(AuthService.User a,String search)throws SQLException{String t="%"+(search==null?"":search.trim())+"%",scope=a.headDoctor()?"":" AND owner_id=?";String q="SELECT id,name,age,contact,doctor,diagnosis,status,owner_id FROM patients WHERE(name LIKE? OR contact LIKE? OR doctor LIKE? OR diagnosis LIKE?)"+scope+" ORDER BY id DESC";List<Patient> out=new ArrayList<>();try(Connection c=db.connect();PreparedStatement s=c.prepareStatement(q)){for(int i=1;i<=4;i++)s.setString(i,t);if(!a.headDoctor())s.setLong(5,a.id());try(ResultSet r=s.executeQuery()){while(r.next())out.add(new Patient(r.getLong(1),r.getString(2),r.getInt(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getLong(8)));}}return out;}
 public void add(AuthService.User a,String n,int age,String contact,String doctor,String diagnosis,String status)throws SQLException{validate(n,age,contact);try(Connection c=db.connect();PreparedStatement s=c.prepareStatement("INSERT INTO patients(name,age,contact,doctor,diagnosis,status,owner_id)VALUES(?,?,?,?,?,?,?)")){fill(s,n,age,contact,doctor,diagnosis,status);s.setLong(7,a.id());s.executeUpdate();}}
 public void update(AuthService.User a,long id,String n,int age,String contact,String doctor,String diagnosis,String status)throws SQLException{validate(n,age,contact);String scope=a.headDoctor()?"":" AND owner_id=?";try(Connection c=db.connect();PreparedStatement s=c.prepareStatement("UPDATE patients SET name=?,age=?,contact=?,doctor=?,diagnosis=?,status=? WHERE id=?"+scope)){fill(s,n,age,contact,doctor,diagnosis,status);s.setLong(7,id);if(!a.headDoctor())s.setLong(8,a.id());if(s.executeUpdate()!=1)throw new IllegalArgumentException("Patient not found or access denied.");}}
 public void delete(AuthService.User a,long id)throws SQLException{String q="DELETE FROM patients WHERE id=?"+(a.headDoctor()?"":" AND owner_id=?");try(Connection c=db.connect();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);if(!a.headDoctor())s.setLong(2,a.id());if(s.executeUpdate()!=1)throw new IllegalArgumentException("Patient not found or access denied.");}}
 private static void fill(PreparedStatement s,String n,int age,String c,String d,String x,String st)throws SQLException{s.setString(1,n.trim());s.setInt(2,age);s.setString(3,c.trim());s.setString(4,v(d));s.setString(5,v(x));s.setString(6,v(st));}private static String v(String x){return x==null?"":x.trim();}private static void validate(String n,int a,String c){if(n==null||n.isBlank())throw new IllegalArgumentException("Patient name is required.");if(a<0||a>120)throw new IllegalArgumentException("Age must be between 0 and 120.");if(c==null||c.isBlank())throw new IllegalArgumentException("Contact is required.");}
}
